/* hand-written; not generated. Databricks twin of dbt/models/tags/tag_entity.sql: one row per */ /* (entity_type, workspace_id, entity_id, tag_key) for every place a Databricks object carries a */ /* tag. Whole snapshot, complete days only -- no 30 marker. 0.6/ */ /* 0.5 (and their _PCT display twins) are filled in at export time from */ /* config/settings.yml, same as 30. */ /* The 7 billed_* entity types (tags.tag_entity_billed_inference in the dbt macro) are combined into */ /* one shared pipeline below (billed_all onward), partitioned by entity_type as well as entity_id, */ /* rather than one hand-copied block per type -- same result, far less repetition. */ WITH wsh_billed /* ============================================================================================= */ /* workspace: the current row of the workspace tag history (shared _workspace_history.sql block). */ /* ============================================================================================= */ /* hand-written; not generated. Databricks twin of dbt/models/tags/tag_workspace_history.sql, as CTEs */ /* only: tools/export_direct_results.py pastes it where a tags query says __WORKSPACE_HISTORY__, and */ /* that query reads ws_history -- one row per (workspace_id, tag_key, valid_from), the workspace's */ /* tag inferred per billed day from sysx.billing.usage.custom_tags. A run of days with one value */ /* is a version once it has held 3 days (to the next change, or to today); a shorter run stays in */ /* the version before it. The first version starts on the workspace's first billed day, so days */ /* before a tag first showed read '__untagged__'. valid_to is exclusive, NULL on the current row. */ AS (SELECT ROW_NUMBER() OVER () AS rid, u.workspace_id, u.usage_date, u.usage_quantity, u.custom_tags FROM "sysx"."billing"."usage" AS u WHERE u.usage_unit = 'DBU' AND NOT u.workspace_id IS NULL AND u.usage_date < CAST('2026-09-21' AS DATE) AND u.ingestion_date < CAST('2026-09-21' AS DATE) AND /* an Azure workspace tag reaches serverless usage as well as classic compute, and a usage */ /* policy's tags are the policy's, not the workspace's */ u.usage_metadata.budget_policy_id IS NULL AND u.usage_metadata.usage_policy_id IS NULL), wsh_day_totals AS (SELECT workspace_id, usage_date, SUM(usage_quantity) AS dbus_total FROM wsh_billed GROUP BY workspace_id, usage_date), wsh_pairs AS (/* one (row, normalised key) pair; when a map holds two spellings of one key, the */ /* alphabetically first raw key wins */ SELECT b.workspace_id, b.usage_date, b.usage_quantity, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value FROM wsh_billed AS b CROSS JOIN LATERAL (SELECT unnest(map_keys(b.custom_tags)) AS raw_key, unnest(map_values(b.custom_tags)) AS raw_value) AS x WHERE NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY b.rid, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), wsh_day_values AS (SELECT workspace_id, tag_key, usage_date, tag_value, SUM(usage_quantity) AS dbus FROM wsh_pairs GROUP BY workspace_id, tag_key, usage_date, tag_value), wsh_day_top AS (SELECT workspace_id, tag_key, usage_date, tag_value, dbus, SUM(dbus) OVER (PARTITION BY workspace_id, tag_key, usage_date) AS dbus_tagged, ROW_NUMBER() OVER (PARTITION BY workspace_id, tag_key, usage_date ORDER BY dbus DESC, tag_value NULLS FIRST) AS rn FROM wsh_day_values), wsh_day_state AS (/* every billed day of the workspace for every key it ever carried */ SELECT k.workspace_id, k.tag_key, t.usage_date, CASE WHEN d.dbus_tagged IS NULL OR d.dbus_tagged / NULLIF(t.dbus_total, 0) < 0.5 OR t.dbus_total <= 0 THEN '__untagged__' WHEN d.dbus / NULLIF(d.dbus_tagged, 0) >= 0.6 THEN d.tag_value ELSE '__mixed__' END AS state FROM (SELECT DISTINCT workspace_id, tag_key FROM wsh_day_values) AS k JOIN wsh_day_totals AS t ON t.workspace_id = k.workspace_id LEFT JOIN wsh_day_top AS d ON d.workspace_id = k.workspace_id AND d.tag_key = k.tag_key AND d.usage_date = t.usage_date AND d.rn = 1), wsh_runs AS (SELECT workspace_id, tag_key, state, MIN(usage_date) AS run_from FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY workspace_id, tag_key ORDER BY usage_date NULLS FIRST) - ROW_NUMBER() OVER (PARTITION BY workspace_id, tag_key, state ORDER BY usage_date NULLS FIRST) AS grp FROM wsh_day_state) AS d GROUP BY workspace_id, tag_key, state, grp), wsh_kept AS (/* a run stands once it has held 3 days, counted to the next run or to today */ SELECT *, CASE WHEN DATE_DIFF('DAY', run_from, COALESCE(LEAD(run_from) OVER (PARTITION BY workspace_id, tag_key ORDER BY run_from NULLS FIRST), CAST('2026-09-21' AS DATE))) >= 3 THEN state END AS kept_state FROM wsh_runs), wsh_smoothed AS (/* a short run takes the value of the last run that stands before it; a short first run keeps its own */ SELECT workspace_id, tag_key, run_from, COALESCE(kept_state, LAST_VALUE(kept_state IGNORE NULLS) OVER (PARTITION BY workspace_id, tag_key ORDER BY run_from NULLS FIRST ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), state) AS state FROM wsh_kept), wsh_versions AS (SELECT workspace_id, tag_key, state AS tag_value, MIN(run_from) AS valid_from FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY workspace_id, tag_key ORDER BY run_from NULLS FIRST) - ROW_NUMBER() OVER (PARTITION BY workspace_id, tag_key, state ORDER BY run_from NULLS FIRST) AS grp FROM wsh_smoothed) AS s GROUP BY workspace_id, tag_key, state, grp), wsh_dated AS (SELECT *, LEAD(valid_from) OVER (PARTITION BY workspace_id, tag_key ORDER BY valid_from NULLS FIRST) AS valid_to FROM wsh_versions), wsh_version_values AS (SELECT v.workspace_id, v.tag_key, v.valid_from, d.tag_value, SUM(d.dbus) AS dbus FROM wsh_dated AS v JOIN wsh_day_values AS d ON d.workspace_id = v.workspace_id AND d.tag_key = v.tag_key AND d.usage_date >= v.valid_from AND (v.valid_to IS NULL OR d.usage_date < v.valid_to) GROUP BY v.workspace_id, v.tag_key, v.valid_from, d.tag_value), wsh_version_ranked AS (SELECT *, SUM(dbus) OVER (PARTITION BY workspace_id, tag_key, valid_from) AS dbus_tagged, ROW_NUMBER() OVER (PARTITION BY workspace_id, tag_key, valid_from ORDER BY dbus DESC, tag_value NULLS FIRST) AS rn FROM wsh_version_values), wsh_top_values AS (SELECT workspace_id, tag_key, valid_from, LIST_TRANSFORM(ARRAY_SORT(ARRAY_AGG({'rn': rn, 'v': tag_value}) FILTER(WHERE {'rn': rn, 'v': tag_value} IS NOT NULL)), x -> x.v) AS top_values FROM wsh_version_ranked WHERE rn <= 5 GROUP BY workspace_id, tag_key, valid_from), wsh_version_totals AS (SELECT v.workspace_id, v.tag_key, v.valid_from, SUM(t.dbus_total) AS dbus_total FROM wsh_dated AS v JOIN wsh_day_totals AS t ON t.workspace_id = v.workspace_id AND t.usage_date >= v.valid_from AND (v.valid_to IS NULL OR t.usage_date < v.valid_to) GROUP BY v.workspace_id, v.tag_key, v.valid_from), wsh_display AS (/* the raw spelling carrying the most DBUs account-wide names the key on screen */ SELECT tag_key, raw_key AS display_key FROM (SELECT tag_key, raw_key, ROW_NUMBER() OVER (PARTITION BY tag_key ORDER BY SUM(usage_quantity) DESC, raw_key NULLS FIRST) AS rn FROM wsh_pairs GROUP BY tag_key, raw_key) AS d WHERE rn = 1), wsh_measured AS (SELECT v.workspace_id, v.tag_key, d.display_key, v.tag_value, v.valid_from, v.valid_to, r.tag_value AS top_value, tv.top_values, r.dbus / NULLIF(r.dbus_tagged, 0) AS share, COALESCE(r.dbus_tagged, 0) / NULLIF(t.dbus_total, 0) AS coverage, COALESCE(r.dbus_tagged, 0) AS dbus_tagged, t.dbus_total, CASE WHEN v.valid_to IS NULL THEN 'since ' || CAST(v.valid_from AS TEXT) ELSE 'from ' || CAST(v.valid_from AS TEXT) || ' to ' || CAST(CAST(v.valid_to AS DATE) + INTERVAL (1 * -1) DAY AS TEXT) END AS period FROM wsh_dated AS v JOIN wsh_version_totals AS t ON t.workspace_id = v.workspace_id AND t.tag_key = v.tag_key AND t.valid_from = v.valid_from JOIN wsh_display AS d ON d.tag_key = v.tag_key LEFT JOIN wsh_version_ranked AS r ON r.workspace_id = v.workspace_id AND r.tag_key = v.tag_key AND r.valid_from = v.valid_from AND r.rn = 1 LEFT JOIN wsh_top_values AS tv ON tv.workspace_id = v.workspace_id AND tv.tag_key = v.tag_key AND tv.valid_from = v.valid_from), ws_history AS (SELECT workspace_id, tag_key, display_key, tag_value, NOT tag_value IN ('__mixed__', '__untagged__') AS is_allocating, valid_from, valid_to, valid_to IS NULL AS is_current, top_value, top_values, share, coverage, dbus_tagged, dbus_total, CASE WHEN top_value IS NULL THEN period || ': no billed usage of this workspace carries ' || display_key WHEN tag_value = '__untagged__' THEN period || ': only ' || CAST(ROUND(COALESCE(coverage, 0) * 100, 1) AS TEXT) || '% of this workspace''s billed DBUs carry ' || display_key || ' (top value "' || top_value || '"); at least 50.0% is needed to infer a workspace tag' WHEN tag_value = '__mixed__' THEN period || ': no single ' || display_key || ' value reaches 60.0% of the ' || display_key || '-tagged DBUs (top "' || top_value || '" at ' || CAST(ROUND(share * 100, 1) AS TEXT) || '%); tagged DBUs are ' || CAST(ROUND(coverage * 100, 1) AS TEXT) || '% of this workspace''s billed DBUs' ELSE period || ': ' || display_key || ' "' || tag_value || '" carries ' || CAST(ROUND(share * 100, 1) AS TEXT) || '% of the ' || display_key || '-tagged DBUs, which are ' || CAST(ROUND(coverage * 100, 1) AS TEXT) || '% of this workspace''s billed DBUs' END AS reason FROM wsh_measured), workspace_entity AS (SELECT 'workspace' AS entity_type, workspace_id, workspace_id AS entity_id, tag_key, display_key AS raw_key, tag_value, is_allocating, 'workspace_inferred' AS source, share, coverage, reason FROM ws_history WHERE is_current), warehouse_latest /* ============================================================================================= */ /* warehouse: latest compute.warehouses.tags. */ /* ============================================================================================= */ AS (SELECT warehouse_id, workspace_id, tags, ROW_NUMBER() OVER (PARTITION BY warehouse_id ORDER BY change_time DESC) AS rn FROM "sysx"."compute"."warehouses"), warehouse_pairs AS (SELECT w.warehouse_id, w.workspace_id, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value FROM warehouse_latest AS w CROSS JOIN LATERAL (SELECT unnest(map_keys(w.tags)) AS raw_key, unnest(map_values(w.tags)) AS raw_value) AS x WHERE w.rn = 1 AND NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY w.warehouse_id, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), warehouse_entity AS (SELECT 'warehouse' AS entity_type, workspace_id, warehouse_id AS entity_id, tag_key, raw_key, tag_value, TRUE AS is_allocating, 'warehouse_tags' AS source, CAST(NULL AS DOUBLE) AS share, CAST(NULL AS DOUBLE) AS coverage, CAST(NULL AS TEXT) AS reason FROM warehouse_pairs), pool_latest /* ============================================================================================= */ /* pool: latest compute.instance_pools.tags. Shared with the cluster fallback below. */ /* ============================================================================================= */ AS (SELECT instance_pool_id, workspace_id, tags, ROW_NUMBER() OVER (PARTITION BY instance_pool_id ORDER BY change_time DESC) AS rn FROM "sysx"."compute"."instance_pools"), pool_pairs AS (SELECT p.instance_pool_id, p.workspace_id, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value FROM pool_latest AS p CROSS JOIN LATERAL (SELECT unnest(map_keys(p.tags)) AS raw_key, unnest(map_values(p.tags)) AS raw_value) AS x WHERE p.rn = 1 AND NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY p.instance_pool_id, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), pool_entity AS (SELECT 'pool' AS entity_type, workspace_id, instance_pool_id AS entity_id, tag_key, raw_key, tag_value, TRUE AS is_allocating, 'pool_tags' AS source, CAST(NULL AS DOUBLE) AS share, CAST(NULL AS DOUBLE) AS coverage, CAST(NULL AS TEXT) AS reason FROM pool_pairs), cluster_latest /* ============================================================================================= */ /* cluster: its own tags, plus (for a key it does not carry) its pool's tag, worker pool first. */ /* ============================================================================================= */ AS (SELECT cluster_id, workspace_id, tags, worker_instance_pool_id, driver_instance_pool_id, ROW_NUMBER() OVER (PARTITION BY cluster_id ORDER BY change_time DESC) AS rn FROM "sysx"."compute"."clusters"), cluster_own_pairs AS (SELECT c.cluster_id, c.workspace_id, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value FROM cluster_latest AS c CROSS JOIN LATERAL (SELECT unnest(map_keys(c.tags)) AS raw_key, unnest(map_values(c.tags)) AS raw_value) AS x WHERE c.rn = 1 AND NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY c.cluster_id, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), cluster_pool_fallback AS (SELECT c.cluster_id, c.workspace_id, wp.raw_key, wp.tag_key, wp.tag_value FROM cluster_latest AS c JOIN pool_pairs AS wp ON wp.instance_pool_id = c.worker_instance_pool_id WHERE c.rn = 1 AND NOT c.worker_instance_pool_id IS NULL UNION ALL SELECT c.cluster_id, c.workspace_id, dp.raw_key, dp.tag_key, dp.tag_value FROM cluster_latest AS c JOIN pool_pairs AS dp ON dp.instance_pool_id = c.driver_instance_pool_id WHERE c.rn = 1 AND NOT c.driver_instance_pool_id IS NULL AND NOT EXISTS(SELECT 1 FROM pool_pairs AS wp2 WHERE wp2.instance_pool_id = c.worker_instance_pool_id AND wp2.tag_key = dp.tag_key)), cluster_pool_fallback_unclaimed AS (SELECT f.cluster_id, f.workspace_id, f.raw_key, f.tag_key, f.tag_value FROM cluster_pool_fallback AS f WHERE NOT EXISTS(SELECT 1 FROM cluster_own_pairs AS o WHERE o.cluster_id = f.cluster_id AND o.tag_key = f.tag_key)), cluster_entity AS (SELECT 'cluster' AS entity_type, workspace_id, cluster_id AS entity_id, tag_key, raw_key, tag_value, TRUE AS is_allocating, 'cluster_tags' AS source, CAST(NULL AS DOUBLE) AS share, CAST(NULL AS DOUBLE) AS coverage, CAST(NULL AS TEXT) AS reason FROM cluster_own_pairs UNION ALL SELECT 'cluster' AS entity_type, workspace_id, cluster_id AS entity_id, tag_key, raw_key, tag_value, TRUE AS is_allocating, 'pool_tags' AS source, CAST(NULL AS DOUBLE) AS share, CAST(NULL AS DOUBLE) AS coverage, CAST(NULL AS TEXT) AS reason FROM cluster_pool_fallback_unclaimed), job_latest /* ============================================================================================= */ /* job / pipeline: latest lakeflow.jobs.tags / lakeflow.pipelines.tags. */ /* ============================================================================================= */ AS (SELECT job_id, workspace_id, tags, ROW_NUMBER() OVER (PARTITION BY workspace_id, job_id ORDER BY change_time DESC) AS rn FROM "sysx"."lakeflow"."jobs"), job_pairs AS (SELECT j.job_id, j.workspace_id, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value FROM job_latest AS j CROSS JOIN LATERAL (SELECT unnest(map_keys(j.tags)) AS raw_key, unnest(map_values(j.tags)) AS raw_value) AS x WHERE j.rn = 1 AND NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY j.workspace_id, j.job_id, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), job_entity AS (SELECT 'job' AS entity_type, workspace_id, job_id AS entity_id, tag_key, raw_key, tag_value, TRUE AS is_allocating, 'job_tags' AS source, CAST(NULL AS DOUBLE) AS share, CAST(NULL AS DOUBLE) AS coverage, CAST(NULL AS TEXT) AS reason FROM job_pairs), pipeline_latest AS (SELECT pipeline_id, workspace_id, tags, ROW_NUMBER() OVER (PARTITION BY workspace_id, pipeline_id ORDER BY change_time DESC) AS rn FROM "sysx"."lakeflow"."pipelines"), pipeline_pairs AS (SELECT p.pipeline_id, p.workspace_id, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value FROM pipeline_latest AS p CROSS JOIN LATERAL (SELECT unnest(map_keys(p.tags)) AS raw_key, unnest(map_values(p.tags)) AS raw_value) AS x WHERE p.rn = 1 AND NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY p.workspace_id, p.pipeline_id, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), pipeline_entity AS (SELECT 'pipeline' AS entity_type, workspace_id, pipeline_id AS entity_id, tag_key, raw_key, tag_value, TRUE AS is_allocating, 'pipeline_tags' AS source, CAST(NULL AS DOUBLE) AS share, CAST(NULL AS DOUBLE) AS coverage, CAST(NULL AS TEXT) AS reason FROM pipeline_pairs), statement_pairs /* ============================================================================================= */ /* statement: query.history.query_tags, whole snapshot. */ /* ============================================================================================= */ AS (SELECT q.statement_id, q.workspace_id, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value FROM "sysx"."query"."history" AS q CROSS JOIN LATERAL (SELECT unnest(map_keys(q.query_tags)) AS raw_key, unnest(map_values(q.query_tags)) AS raw_value) AS x WHERE NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY q.statement_id, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), statement_entity AS (SELECT 'statement' AS entity_type, workspace_id, statement_id AS entity_id, tag_key, raw_key, tag_value, TRUE AS is_allocating, 'query_tags' AS source, CAST(NULL AS DOUBLE) AS share, CAST(NULL AS DOUBLE) AS coverage, CAST(NULL AS TEXT) AS reason FROM statement_pairs), uc_table_pairs /* ============================================================================================= */ /* Unity Catalog object tags: already flat (catalog/schema[/table[/column|volume]], tag_name, */ /* tag_value) -- no map to explode. workspace_id is NULL: a UC object has no workspace. */ /* ============================================================================================= */ AS (SELECT LOWER(t.catalog_name) || '.' || LOWER(t.schema_name) || '.' || LOWER(t.table_name) AS entity_id, t.tag_name AS raw_key, REGEXP_REPLACE(LOWER(t.tag_name), '[ _-]+', '', 'g') AS tag_key, TRIM(t.tag_value) AS tag_value FROM "sysx"."information_schema"."table_tags" AS t WHERE NOT t.tag_name IS NULL AND NOT t.tag_value IS NULL AND REGEXP_REPLACE(LOWER(t.tag_name), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(t.catalog_name), LOWER(t.schema_name), LOWER(t.table_name), REGEXP_REPLACE(LOWER(t.tag_name), '[ _-]+', '', 'g') ORDER BY t.tag_name NULLS FIRST) = 1), uc_table_entity AS (SELECT 'uc_table' AS entity_type, CAST(NULL AS TEXT) AS workspace_id, entity_id, tag_key, raw_key, tag_value, TRUE AS is_allocating, 'uc_table_tags' AS source, CAST(NULL AS DOUBLE) AS share, CAST(NULL AS DOUBLE) AS coverage, CAST(NULL AS TEXT) AS reason FROM uc_table_pairs), uc_schema_pairs AS (SELECT LOWER(s.catalog_name) || '.' || LOWER(s.schema_name) AS entity_id, s.tag_name AS raw_key, REGEXP_REPLACE(LOWER(s.tag_name), '[ _-]+', '', 'g') AS tag_key, TRIM(s.tag_value) AS tag_value FROM "sysx"."information_schema"."schema_tags" AS s WHERE NOT s.tag_name IS NULL AND NOT s.tag_value IS NULL AND REGEXP_REPLACE(LOWER(s.tag_name), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(s.catalog_name), LOWER(s.schema_name), REGEXP_REPLACE(LOWER(s.tag_name), '[ _-]+', '', 'g') ORDER BY s.tag_name NULLS FIRST) = 1), uc_schema_entity AS (SELECT 'uc_schema' AS entity_type, CAST(NULL AS TEXT) AS workspace_id, entity_id, tag_key, raw_key, tag_value, TRUE AS is_allocating, 'uc_schema_tags' AS source, CAST(NULL AS DOUBLE) AS share, CAST(NULL AS DOUBLE) AS coverage, CAST(NULL AS TEXT) AS reason FROM uc_schema_pairs), uc_column_pairs AS (SELECT LOWER(c.catalog_name) || '.' || LOWER(c.schema_name) || '.' || LOWER(c.table_name) || '.' || LOWER(c.column_name) AS entity_id, c.tag_name AS raw_key, REGEXP_REPLACE(LOWER(c.tag_name), '[ _-]+', '', 'g') AS tag_key, TRIM(c.tag_value) AS tag_value FROM "sysx"."information_schema"."column_tags" AS c WHERE NOT c.tag_name IS NULL AND NOT c.tag_value IS NULL AND REGEXP_REPLACE(LOWER(c.tag_name), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(c.catalog_name), LOWER(c.schema_name), LOWER(c.table_name), LOWER(c.column_name), REGEXP_REPLACE(LOWER(c.tag_name), '[ _-]+', '', 'g') ORDER BY c.tag_name NULLS FIRST) = 1), uc_column_entity AS (SELECT 'uc_column' AS entity_type, CAST(NULL AS TEXT) AS workspace_id, entity_id, tag_key, raw_key, tag_value, TRUE AS is_allocating, 'uc_column_tags' AS source, CAST(NULL AS DOUBLE) AS share, CAST(NULL AS DOUBLE) AS coverage, CAST(NULL AS TEXT) AS reason FROM uc_column_pairs), uc_volume_pairs AS (SELECT LOWER(v.catalog_name) || '.' || LOWER(v.schema_name) || '.' || LOWER(v.volume_name) AS entity_id, v.tag_name AS raw_key, REGEXP_REPLACE(LOWER(v.tag_name), '[ _-]+', '', 'g') AS tag_key, TRIM(v.tag_value) AS tag_value FROM "sysx"."information_schema"."volume_tags" AS v WHERE NOT v.tag_name IS NULL AND NOT v.tag_value IS NULL AND REGEXP_REPLACE(LOWER(v.tag_name), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(v.catalog_name), LOWER(v.schema_name), LOWER(v.volume_name), REGEXP_REPLACE(LOWER(v.tag_name), '[ _-]+', '', 'g') ORDER BY v.tag_name NULLS FIRST) = 1), uc_volume_entity AS (SELECT 'uc_volume' AS entity_type, CAST(NULL AS TEXT) AS workspace_id, entity_id, tag_key, raw_key, tag_value, TRUE AS is_allocating, 'uc_volume_tags' AS source, CAST(NULL AS DOUBLE) AS share, CAST(NULL AS DOUBLE) AS coverage, CAST(NULL AS TEXT) AS reason FROM uc_volume_pairs), billed_usage /* ============================================================================================= */ /* billed_*: the dominant billing.usage.custom_tags value per billed entity id (section 3.3). The */ /* 7 macro calls in dbt/models/tags/tag_entity.sql are one shared pipeline here, partitioned by */ /* entity_type as well as entity_id so the 7 types never mix. */ /* ============================================================================================= */ AS (SELECT ROW_NUMBER() OVER () AS rid, workspace_id, usage_quantity, custom_tags, usage_metadata.warehouse_id AS warehouse_id, usage_metadata.cluster_id AS cluster_id, usage_metadata.instance_pool_id AS instance_pool_id, usage_metadata.endpoint_id AS endpoint_id, usage_metadata.endpoint_name AS endpoint_name, usage_metadata.job_id AS job_id, usage_metadata.dlt_pipeline_id AS dlt_pipeline_id, CASE WHEN NOT usage_metadata.warehouse_id IS NULL THEN 'billing:warehouse' WHEN NOT usage_metadata.cluster_id IS NULL THEN 'billing:cluster' WHEN NOT usage_metadata.endpoint_id IS NULL OR NOT usage_metadata.endpoint_name IS NULL THEN 'billing:endpoint' WHEN NOT usage_metadata.app_id IS NULL THEN 'billing:app' WHEN NOT usage_metadata.job_id IS NULL OR NOT usage_metadata.dlt_pipeline_id IS NULL OR NOT usage_metadata.notebook_id IS NULL OR NOT usage_metadata.budget_policy_id IS NULL OR NOT usage_metadata.usage_policy_id IS NULL OR product_features.is_serverless THEN CASE WHEN NOT usage_metadata.budget_policy_id IS NULL OR NOT usage_metadata.usage_policy_id IS NULL THEN 'billing:budget_policy' ELSE 'billing:serverless' END ELSE 'billing:other' END AS row_source FROM "sysx"."billing"."usage" WHERE usage_unit = 'DBU' AND NOT workspace_id IS NULL AND usage_date < CAST('2026-09-21' AS DATE) AND ingestion_date < CAST('2026-09-21' AS DATE)), billed_all AS (SELECT rid, workspace_id, 'billed_warehouse' AS entity_type, warehouse_id AS entity_id, usage_quantity, custom_tags, row_source AS source FROM billed_usage WHERE NOT warehouse_id IS NULL UNION ALL SELECT rid, workspace_id, 'billed_cluster', cluster_id, usage_quantity, custom_tags, row_source FROM billed_usage WHERE NOT cluster_id IS NULL UNION ALL SELECT rid, workspace_id, 'billed_pool', instance_pool_id, usage_quantity, custom_tags, row_source FROM billed_usage WHERE NOT instance_pool_id IS NULL UNION ALL SELECT rid, workspace_id, 'billed_endpoint', endpoint_id, usage_quantity, custom_tags, row_source FROM billed_usage WHERE NOT endpoint_id IS NULL UNION ALL /* only when endpoint_id is absent: never double-counts a row under both billed_endpoint types. */ SELECT rid, workspace_id, 'billed_endpoint_name', endpoint_name, usage_quantity, custom_tags, row_source FROM billed_usage WHERE endpoint_id IS NULL AND NOT endpoint_name IS NULL UNION ALL SELECT rid, workspace_id, 'billed_job', job_id, usage_quantity, custom_tags, row_source FROM billed_usage WHERE NOT job_id IS NULL UNION ALL SELECT rid, workspace_id, 'billed_pipeline', dlt_pipeline_id, usage_quantity, custom_tags, row_source FROM billed_usage WHERE NOT dlt_pipeline_id IS NULL), billed_pairs AS (SELECT ba.entity_type, ba.workspace_id, ba.entity_id, ba.rid, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value, ba.usage_quantity, ba.source FROM billed_all AS ba CROSS JOIN LATERAL (SELECT unnest(map_keys(ba.custom_tags)) AS raw_key, unnest(map_values(ba.custom_tags)) AS raw_value) AS x WHERE NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY ba.entity_type, ba.rid, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), billed_per_value AS (SELECT entity_type, workspace_id, entity_id, tag_key, tag_value, SUM(usage_quantity) AS dbus, ARG_MAX(source, usage_quantity) AS src FROM billed_pairs GROUP BY entity_type, workspace_id, entity_id, tag_key, tag_value), billed_per_key AS (SELECT entity_type, workspace_id, entity_id, tag_key, SUM(dbus) AS dbus_tagged FROM billed_per_value GROUP BY entity_type, workspace_id, entity_id, tag_key), billed_totals AS (SELECT entity_type, workspace_id, entity_id, SUM(usage_quantity) AS dbus_total FROM billed_all GROUP BY entity_type, workspace_id, entity_id), billed_ranked AS (SELECT entity_type, workspace_id, entity_id, tag_key, tag_value, dbus, src, ROW_NUMBER() OVER (PARTITION BY entity_type, workspace_id, entity_id, tag_key ORDER BY dbus DESC, tag_value NULLS FIRST) AS rn FROM billed_per_value), billed_display AS (SELECT entity_type, workspace_id, entity_id, tag_key, raw_key, ROW_NUMBER() OVER (PARTITION BY entity_type, workspace_id, entity_id, tag_key ORDER BY SUM(usage_quantity) DESC, raw_key NULLS FIRST) AS rn FROM billed_pairs GROUP BY entity_type, workspace_id, entity_id, tag_key, raw_key), billed_measured AS (SELECT r.entity_type, r.workspace_id, r.entity_id, r.tag_key, d.raw_key, r.tag_value AS top_value, r.src AS source, r.dbus / NULLIF(k.dbus_tagged, 0) AS share, k.dbus_tagged / NULLIF(t.dbus_total, 0) AS coverage FROM billed_ranked AS r JOIN billed_per_key AS k ON k.entity_type = r.entity_type AND k.workspace_id = r.workspace_id AND k.entity_id = r.entity_id AND k.tag_key = r.tag_key JOIN billed_totals AS t ON t.entity_type = r.entity_type AND t.workspace_id = r.workspace_id AND t.entity_id = r.entity_id JOIN billed_display AS d ON d.entity_type = r.entity_type AND d.workspace_id = r.workspace_id AND d.entity_id = r.entity_id AND d.tag_key = r.tag_key AND d.rn = 1 WHERE r.rn = 1), billed_entity AS (SELECT entity_type, workspace_id, entity_id, tag_key, raw_key, CASE WHEN coverage IS NULL OR coverage < 0.5 THEN '__untagged__' WHEN share >= 0.6 THEN top_value ELSE '__mixed__' END AS tag_value, (coverage >= 0.5 AND share >= 0.6) IS TRUE AS is_allocating, source, share, coverage, CASE WHEN coverage IS NULL OR coverage < 0.5 THEN 'only ' || CAST(ROUND(COALESCE(coverage, 0) * 100, 1) AS TEXT) || '% of this ' || entity_type || '''s billed DBUs carry ' || raw_key || ' (top value "' || top_value || '"); at least 50.0% is needed to infer a tag' WHEN share >= 0.6 THEN raw_key || ' "' || top_value || '" carries ' || CAST(ROUND(share * 100, 1) AS TEXT) || '% of the ' || raw_key || '-tagged DBUs, which are ' || CAST(ROUND(coverage * 100, 1) AS TEXT) || '% of this ' || entity_type || '''s billed DBUs' ELSE 'no single ' || raw_key || ' value reaches 60.0% of the ' || raw_key || '-tagged DBUs (top "' || top_value || '" at ' || CAST(ROUND(share * 100, 1) AS TEXT) || '%); tagged DBUs are ' || CAST(ROUND(coverage * 100, 1) AS TEXT) || '% of this ' || entity_type || '''s billed DBUs' END AS reason FROM billed_measured) SELECT * FROM (SELECT * FROM workspace_entity UNION ALL SELECT * FROM warehouse_entity UNION ALL SELECT * FROM pool_entity UNION ALL SELECT * FROM cluster_entity UNION ALL SELECT * FROM job_entity UNION ALL SELECT * FROM pipeline_entity UNION ALL SELECT * FROM statement_entity UNION ALL SELECT * FROM uc_table_entity UNION ALL SELECT * FROM uc_schema_entity UNION ALL SELECT * FROM uc_column_entity UNION ALL SELECT * FROM uc_volume_entity UNION ALL SELECT * FROM billed_entity) AS all_entities /* settings export_tag_keys, filled in at export time: TRUE keeps every tag */ WHERE TRUE